/* EstudaLab: question variety engine (stable across attempts). */
const quizShuffle = list => {
  const arr=[...list];
  for(let i=arr.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[arr[i],arr[j]]=[arr[j],arr[i]];}
  return arr;
};
function quizVariety(items,n,namespace,keyOf,topicOf){
  const storageKey='estudalab.quiz.variety.v3.'+namespace;
  let history=[];
  try {const saved=JSON.parse(localStorage.getItem(storageKey)||'[]');history=Array.isArray(saved)?saved.filter(x=>typeof x==='string').slice(-400):[]}catch{}
  const byId=new Map();
  for(const item of items){const id=String(keyOf(item));if(id&&!byId.has(id))byId.set(id,item)}
  const pool=[...byId.values()];
  const selected=[],picked=new Set(),topicCount=new Map();
  const lastSeen=item=>history.lastIndexOf(String(keyOf(item)));
  const topic=item=>String(topicOf(item)||'Geral');
  while(selected.length<Math.min(n,pool.length)){
    let possible=pool.filter(x=>!picked.has(String(keyOf(x))));
    const unseen=possible.filter(x=>lastSeen(x)<0);
    // No question is repeated while any unused question remains in this bank.
    if(unseen.length){possible=unseen}
    else{
      // Once the full bank has been used, bring back the oldest questions first.
      possible.sort((a,b)=>lastSeen(a)-lastSeen(b));
      possible=possible.slice(0,Math.min(possible.length,Math.max(5,(n-selected.length)*2)));
    }
    const minimum=Math.min(...possible.map(x=>topicCount.get(topic(x))||0));
    let candidates=possible.filter(x=>(topicCount.get(topic(x))||0)===minimum);
    if(!unseen.length){const oldest=Math.min(...candidates.map(lastSeen));candidates=candidates.filter(x=>lastSeen(x)===oldest)}
    const item=candidates[Math.floor(Math.random()*candidates.length)];
    const id=String(keyOf(item)),cat=topic(item);
    selected.push(item);picked.add(id);topicCount.set(cat,(topicCount.get(cat)||0)+1);
  }
  history=[...history,...selected.map(x=>String(keyOf(x)))].slice(-400);
  try{localStorage.setItem(storageKey,JSON.stringify(history))}catch{}
  return quizShuffle(selected);
}
function randomizedAnswers(original,optionsField,answerField){
  const item={...original};
  const options=original[optionsField].map((value,index)=>({value,isCorrect:index===original[answerField]}));
  const randomized=quizShuffle(options);
  item[optionsField]=randomized.map(x=>x.value);
  item[answerField]=randomized.findIndex(x=>x.isCorrect);
  return item;
}
function randomizedMath(q){
  const options=quizShuffle(q[2].map((value,index)=>({value,isCorrect:index===q[3]})));
  return [q[0],q[1],options.map(v=>v.value),options.findIndex(v=>v.isCorrect),q[4]];
}


function writingArea(q){
  const t=q[0].toLowerCase();
  if(/interven|conclus|agente|detalh|finalidade|medida|proposta|meio\/modo/.test(t))return 'Proposta de intervenção';
  if(/competência i |norma|concord|pontua|ortograf|crase|gramát|revisar c1/.test(t))return 'Norma-padrão';
  if(/conect|coesão|embora|entretanto|portanto|por conseguinte|além disso/.test(t))return 'Coesão';
  if(/repertório|citação|tema|referência|recorte|desinformação/.test(t))return 'Tema e repertório';
  return 'Argumentação';
}
function randomizedWriting(q){const opts=quizShuffle(q[1].map((v,i)=>({v,ok:i===q[2]})));return [q[0],opts.map(x=>x.v),opts.findIndex(x=>x.ok),q[3]]}
function pick(arr,n){return quizVariety(arr,n,'redacao',q=>q[0],writingArea).map(randomizedWriting)}
function startQuiz(){quiz={qs:pick([...BANK,...EXTRA_BANK_V7],15),i:0,answered:[],choice:-1,seen:false};renderQuiz()}
function renderQuiz(){const root=$('#quiz-app');if(!quiz){root.innerHTML='<button class="btn" id="begin-quiz">Começar 15 questões</button>';return}const q=quiz.qs[quiz.i];if(!q){const score=quiz.answered.filter((a,i)=>a===quiz.qs[i][2]).length;root.innerHTML=`<h3>Resultado: ${score}/15 acertos</h3><div class="progress"><div style="width:${score/15*100}%"></div></div><p class="muted">Os erros ficam explicados ao final de cada questão. Refaça para encontrar outros temas.</p><button class="btn" id="begin-quiz">Novo simulado de 15</button>`;try{localStorage.setItem('estudalab.redacao.quizbest',String(Math.max(Number(localStorage.getItem('estudalab.redacao.quizbest')||0),score)))}catch{}return}root.innerHTML=`<div class="counter"><span>Questão ${quiz.i+1} de 15</span><span>${quiz.answered.filter((a,j)=>a===quiz.qs[j][2]).length} acertos até aqui</span></div><div class="progress"><div style="width:${(quiz.i/15)*100}%"></div></div><h3>${escapeHTML(q[0])}</h3><div class="quiz-opts">${q[1].map((o,i)=>`<button class="quiz-opt ${quiz.choice===i?'selected':''} ${quiz.seen?(i===q[2]?'good':quiz.choice===i?'bad':''):''}" data-answer="${i}" ${quiz.seen?'disabled':''}>${'ABCD'[i]}) ${escapeHTML(o)}</button>`).join('')}</div>${quiz.seen?`<div class="feedback"><h4>${quiz.choice===q[2]?'✓ Acertou!':'✗ Resposta correta: '+('ABCD'[q[2]])}</h4><p>${escapeHTML(q[3])}</p></div>`:''}<div class="actions" style="margin-top:14px"><button class="btn" id="quiz-next" ${quiz.seen?'':'disabled'}>${quiz.i===14?'Ver resultado':'Próxima questão'}</button></div>`;}
$('#quiz-app').addEventListener('click',e=>{if(e.target.id==='begin-quiz')return startQuiz();const opt=e.target.closest('[data-answer]');if(opt&&quiz&&!quiz.seen){quiz.choice=Number(opt.dataset.answer);quiz.seen=true;quiz.answered[quiz.i]=quiz.choice;renderQuiz();return}if(e.target.id==='quiz-next'&&quiz?.seen){quiz.i++;quiz.choice=-1;quiz.seen=false;renderQuiz()}});
/* initialize after topic-browser state and listeners */

/* Topic browser: categorized proposals, searchable cards, saved favorites and study-room preview. */
const GROUP_INFO={
 'Educação':['📚','Escola, aprendizagem e oportunidades'],
 'Saúde':['🩺','Prevenção, acesso e bem-estar'],
 'Tecnologia e mídia':['💻','Internet, IA e informação'],
 'Meio ambiente':['🌱','Recursos naturais e sustentabilidade'],
 'Direitos e inclusão':['🤝','Dignidade e igualdade'],
 'Trabalho e economia':['💼','Emprego, renda e qualificação'],
 'Cultura e patrimônio':['🎭','Identidade, arte e memória'],
 'Cidadania e política':['🏛️','Participação e democracia'],
 'Cidades e mobilidade':['🏙️','Moradia, espaço urbano e transporte'],
 'Juventude e sociedade':['✨','Relações, hábitos e desafios sociais']
};
let topicFilter='Todos',searchString='',showFavs=false,selectedTopic=null;
let favoriteTopics=[];try{const saved=JSON.parse(localStorage.getItem('estudalab.redacao.favorites.v1')||'[]');if(Array.isArray(saved))favoriteTopics=saved.filter(x=>typeof x==='string')}catch{}
const normalize=s=>String(s||'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const topicByTitle=title=>TOPICS.find(x=>x.title===title);
function saveFavorites(){try{localStorage.setItem('estudalab.redacao.favorites.v1',JSON.stringify(favoriteTopics))}catch{}}
function renderTopics(){const f=normalize(searchString),items=TOPICS.filter(x=>(topicFilter==='Todos'||x.category===topicFilter)&&(!showFavs||favoriteTopics.includes(x.id))&&(!f||normalize(x.title+' '+x.category+' '+x.texts.map(t=>t.body).join(' ')).includes(f)));
 const groups=Object.entries(GROUP_INFO);$('#category-grid').innerHTML=`<button type="button" class="category-tile ${topicFilter==='Todos'?'chosen':''}" data-category="Todos" aria-pressed="${topicFilter==='Todos'}"><span class="cat-emoji">🗂️</span><strong>Todas</strong><small>60 temas</small></button>`+groups.map(([g,[emoji,desc]])=>`<button type="button" class="category-tile ${topicFilter===g?'chosen':''}" data-category="${escapeHTML(g)}" aria-pressed="${topicFilter===g}"><span class="cat-emoji">${emoji}</span><strong>${escapeHTML(g)}</strong><small>${TOPICS.filter(t=>t.category===g).length} propostas</small></button>`).join('');
 $('#theme-list-title').textContent=topicFilter==='Todos'?'Todas as propostas':topicFilter;$('#theme-list-count').textContent=items.length+' temas';$('#topic-count').textContent=TOPICS.length+' disponíveis';$('#theme-favorites').setAttribute('aria-pressed',String(showFavs));$('#theme-favorites').textContent=showFavs?'★ Salvos':'☆ Salvos';$('#theme-search').value=searchString;
 $('#theme-list').innerHTML=items.length?items.map(t=>`<article class="theme-tile"><div class="theme-tile-inner"><span class="small-caps">${escapeHTML(t.category)}</span><h3>${escapeHTML(t.title)}</h3><p>${escapeHTML(t.texts[0].body)}</p><div class="theme-tile-bottom"><button type="button" class="theme-open" data-open="${escapeHTML(t.id)}">Ver proposta e coletânea <span aria-hidden="true">↗</span></button><button type="button" class="favorite ${favoriteTopics.includes(t.id)?'active':''}" data-favorite="${escapeHTML(t.id)}" aria-label="${favoriteTopics.includes(t.id)?'Remover dos':'Adicionar aos'} temas salvos" title="Salvar tema">${favoriteTopics.includes(t.id)?'★':'☆'}</button></div></div></article>`).join(''):'<div class="empty-state">Nenhum tema encontrado. Tente outro termo ou remova o filtro de salvos.</div>';
}
function motivatingTexts(topic){return topic.texts.map((x,i)=>`<article class="motivador"><div class="mot-num">${['01','02','03'][i]}</div><div class="small-caps">${escapeHTML(x.label)}</div><p>${escapeHTML(x.body)}</p></article>`).join('')}
function openTopic(id){const t=TOPICS.find(x=>x.id===id);if(!t)return;selectedTopic=t;$('#proposal-title').textContent=t.title;$('#proposal-category').textContent=GROUP_INFO[t.category][0]+' '+t.category;$('#proposal-texts').innerHTML=motivatingTexts(t);$('#theme-library').hidden=true;$('#proposal-panel').hidden=false;$('#proposal-panel').scrollIntoView({behavior:'smooth',block:'start'});}
function renderEditorThemePreview(){const t=topicByTitle(ui.tema);const box=$('#editor-theme-preview');if(!box)return;if(!t){box.innerHTML=`<div class="panel edit-preview"><div><div class="eyebrow">SEU TEMA</div><h2>${escapeHTML(currentTopic()||'Tema personalizado')}</h2></div><button class="btn secondary" type="button" id="back-to-themes">Escolher outro tema</button></div>`;return}box.innerHTML=`<div class="panel edit-preview"><div class="edit-preview-head"><div><div class="eyebrow">PROPOSTA SELECIONADA · ${escapeHTML(t.category)}</div><h2>${escapeHTML(t.title)}</h2><p class="muted">Leia os textos motivadores antes de produzir sua argumentação.</p></div><button class="btn secondary" type="button" id="back-to-themes">Trocar tema</button></div><details class="motivating-collapse" open><summary>📖 Textos motivadores (3) <span>toque para expandir/recolher</span></summary><div class="motivadores-grid">${motivatingTexts(t)}</div><p class="source-note">Textos originais do EstudaLab, inspirados no formato ENEM. Não são materiais oficiais do Inep.</p></details></div>`}
$('#category-grid').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;topicFilter=b.dataset.category;renderTopics();});
$('#theme-list').addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){const id=fav.dataset.favorite;favoriteTopics=favoriteTopics.includes(id)?favoriteTopics.filter(x=>x!==id):[...favoriteTopics,id];saveFavorites();renderTopics();return}const b=e.target.closest('[data-open]');if(b)openTopic(b.dataset.open)});
$('#theme-search').addEventListener('input',e=>{searchString=e.target.value;renderTopics();});
$('#theme-favorites').addEventListener('click',()=>{showFavs=!showFavs;renderTopics()});
$('#proposal-back').addEventListener('click',()=>{$('#proposal-panel').hidden=true;$('#theme-library').hidden=false;$('#theme-library').scrollIntoView({behavior:'smooth'});});
$('#begin-writing').addEventListener('click',()=>{if(!selectedTopic)return;const newTopic=selectedTopic.title;if(ui.tema!==newTopic&&Object.values(ui.campos).some(x=>x?.trim())&&!confirm('Você tem um rascunho salvo de outro tema. O texto será mantido; quer continuar?'))return;ui.tema=newTopic;$('#tema').value=newTopic;$('#modo').value=$('#quick-mode').value;renderEditor();drafts();setTab('treinar');$('#editor-theme-preview').scrollIntoView({behavior:'smooth'});});
$('#editor-theme-preview').addEventListener('click',e=>{if(e.target.closest('#back-to-themes')){setTab('temas');$('#theme-library').hidden=false;$('#proposal-panel').hidden=true;$('#theme-library').scrollIntoView({behavior:'smooth'})}});
const shell=EstudaLabShell.mount({subject:'redacao',title:'Redação',contentId:'subject-content',items:[{id:'temas',label:'Biblioteca de temas'},{id:'aprender',label:'Como escrever'},{id:'treinar',label:'Editor de redação'},{id:'simulado',label:'Simulados'},{id:'progresso',label:'Histórico de redações'}],navigate:setTab});
const initial=location.hash.replace('#','');setTab(['temas','aprender','treinar','simulado','progresso'].includes(initial)?initial:'temas');
renderTopics();renderEditorThemePreview();

